import sys


def main():
    t = sys.stdin.read().split()
    r, c = int(t[0]), int(t[1])
    idx = 2
    prev = None
    for i in range(r):
        cur = [0] * c
        for j in range(c):
            v = int(t[idx])
            idx += 1
            if i == 0 and j == 0:
                best = 0
            elif i == 0:
                best = cur[j - 1]
            elif j == 0:
                best = prev[j]
            else:
                best = prev[j] if prev[j] > cur[j - 1] else cur[j - 1]
            cur[j] = best + v
        prev = cur
    print(prev[c - 1])


