def f(i, j):
    if i == r - 1 and j == c - 1:
        return g[i][j]
    options = []
    if i + 1 < r:
        options.append(f(i + 1, j))
    if j + 1 < c:
        options.append(f(i, j + 1))
    return g[i][j] + max(options)


